import unittest,re
from tools.kjv_archive import load_register,read
class JoelPouredSpiritTests(unittest.TestCase):
 def test_devouring_host_poured_spirit_and_nested_speakers(self):
  prior,_=load_register('0.10-kjv.174');lang,manifest=load_register('0.10-kjv.175')
  self.assertEqual(prior.lexicon,{k:lang.lexicon[k] for k in prior.lexicon})
  for attr in ('pairs','suffix','prefix','possessors','roman'):self.assertEqual(getattr(prior,attr),getattr(lang,attr))
  cases={c['id'].removeprefix('joel-'):c for c in read(lang.folder/'joel-devouring-host-and-poured-spirit-cases.json')};self.assertEqual(len(cases),73)
